INSERT OR IGNORE INTO manual_sections
  (manual_key, section_key, title, body, sort_order, version, updated_by, updated_at)
VALUES
  ('owner','returning-staff-prompt','Staff ပြန်ဝင်လာချိန် pending inquiry reminder','Staff တစ်ယောက်ကို /unavailable လုပ်ထားပြီး unanswered inquiries ဝင်ထားပါက အဲဒီ staff က bot ကို private chat မှာ နောက်တစ်ကြိမ်အသုံးပြုချိန် pending inquiry count ကို bot က သတိပေးနိုင်ပါတယ်။\n\n✅ Mark me Available & Review ကိုနှိပ်လျှင် staff ကို available အဖြစ်ပြန်သတ်မှတ်ပြီး Staff Inbox ထဲက waiting user topics ကိုပြန်ကြည့်နိုင်ပါတယ်။ User topic ထဲမှာ reply ရေးလျှင် bot က original user private chat ဆီ staff reply အဖြစ် relay လုပ်ပါတယ်။\n\n⏸ Stay Unavailable ကိုနှိပ်လျှင် availability မပြောင်းဘဲ pending inquiries ကို queue ထဲမှာပဲထားပါတယ်။ Pending set မပြောင်းသေးသရွေ့ တူညီတဲ့ reminder ကို ထပ်ခါထပ်ခါမပို့ပါ။',75,1,0,CURRENT_TIMESTAMP),
  ('admin','returning-staff-prompt','Pending inquiry reminder နှင့် ပြန်လည်ဝင်ရောက်ခြင်း','သင် /unavailable ဖြစ်နေချိန် unanswered inquiries ဝင်ထားပြီး bot ကို private chat မှာ ပြန်အသုံးပြုပါက pending inquiry reminder ပေါ်နိုင်ပါတယ်။\n\n✅ Mark me Available & Review ကိုနှိပ်လျှင် available အဖြစ်ပြန်သတ်မှတ်မယ်။ Staff Inbox ထဲက user topic ကိုဖွင့်ပြီး reply ရေးပါ။ Bot က user private chat ဆီ School of Nursing staff reply အဖြစ် relay လုပ်ပါမယ်။\n\n⏸ Stay Unavailable ကိုနှိပ်လျှင် unavailable အဖြစ်ဆက်ရှိနေမယ်။ Pending inquiries ကို queue ထဲမှာထားပြီး နောက် staff သို့မဟုတ် သင်ပြန် available ဖြစ်ချိန် review လုပ်နိုင်ပါတယ်။',75,1,0,CURRENT_TIMESTAMP);
